import { test, expect } from '@playwright/test';

test.describe('Currency Field Formatting', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('https://example.com'); // Replace with the actual URL
  });

  test('should format currency input with commas and two decimal places', async ({ page }) => {
    const currencyInput = page.getByLabel('Currency Amount'); // Replace with the actual label

    await currencyInput.fill('1000');
    await currencyInput.blur(); // Trigger formatting

    const formattedValue = await currencyInput.inputValue();
    expect(formattedValue).toBe('1,000.00');
  });

  test('should update formatting when input is changed', async ({ page }) => {
    const currencyInput = page.getByLabel('Currency Amount'); // Replace with the actual label

    await currencyInput.fill('25000.5');
    await currencyInput.blur(); // Trigger formatting

    const formattedValue = await currencyInput.inputValue();
    expect(formattedValue).toBe('25,000.50');
  });
});
